    "Progress, however slow, is still progress — keep moving.",
    "Excellence is not a destination; it's a continuous journey.",
    "Ask for help when stuck — seeking help is wisdom, not weakness.",
    "Set a timer and work — short bursts of focus work wonders.",
    "Surround yourself with people who push you to be better.",
    "Show up even on the days you don't feel like it — especially those days.",
    "The gap between where you are and where you want to be is filled with effort.",
    "Work in silence; let success make the noise.",
