    "Worry about tomorrow's problems tomorrow — rest in the now.",
    "Laughter releases tension faster than anything else — find something funny.",
    "Music can shift your mood in seconds — use it wisely.",
    "Your feelings are valid — you don't need to explain them to be at peace.",
    "Gentle movement like stretching tells the body to relax.",
    "Five senses check: what do you see, hear, smell, taste, touch right now?",
    "Write down what's bothering you — the paper holds it so you don't have to.",
    "Compassion for yourself is the beginning of compassion for others.",
