    oyuncak:["اللعب العادل يجعل المتعة أكبر.","انتظار الدور يعلّم الصبر.","شارك اللعبة ليكبر الفرح بين الأصدقاء.","الخسارة بهدوء مهارة جميلة.","الخيال يصنع مغامرة جديدة كل يوم."],
    cevre:["كل اختيار أخضر يحمي عالمنا.","حافظ على الماء ولا تهدره.","النظافة تجعل المكان أجمل للجميع.","احترام الكائنات الحية يبدأ بلطف صغير.","إعادة الاستخدام تقلل الهدر وتحمي الطبيعة."],
    caliskan:["الجهد الصغير اليوم يصنع ثقة الغد.","ابدأ بخطوة واحدة ثم أكمل بهدوء.","التركيز القصير أفضل من تشتت طويل.","المثابرة تعني الرجوع بعد التعب.","قسّم العمل الصعب إلى مهام صغيرة."],
    sanat:["كل لون يحكي شعوراً مختلفاً.","الفن يعلّمك أن تنظر بعين جديدة.","لا تخف من الصفحة الفارغة؛ ابدأ بخط واحد.","احترم أدواتك كما تحترم فكرتك.","شارك عملك الجميل بثقة وهدوء."],
    mutfak:["الطبخ مهارة حياة مفيدة وممتعة.","المطبخ النظيف بداية طعام آمن.","جرّب مكوّناً جديداً لتوسّع ذوقك.","قياس المقادير يدرّب التفكير الدقيق.","لا تهدر الطعام؛ خذ قدر حاجتك."],
    aile:["الكلمة اللطيفة تجعل البيت أدفأ.","ساعد في البيت دون انتظار طلب.","الاعتذار الصادق يصلح القلوب.","استمع لمن تحب قبل أن ترد.","لحظة عائلية صغيرة قد تصبح ذكرى كبيرة."],
    ada:["الهدوء يعطي أفكارك مساحة للنمو.","ابتعد قليلاً عن الضجيج لتسمع نفسك.","الراحة القصيرة تعيد الطاقة والتركيز.","انظر إلى شيء جميل ودع ذهنك يهدأ.","السكينة قوة تتدرب عليها كل يوم."],
    sifa:["اختيار صحي صغير يحمي جسمك.","النوم الجيد يساعدك على التعلم واللعب.","الحركة اليومية تمنح الجسم نشاطاً.","اشرب الماء بانتظام واعتنِ بنفسك.","الهدوء والراحة جزء من الصحة."],
    ilkbahar:["كل بداية جديدة فرصة للنمو.","اعتنِ بالنبتة الصغيرة كما تعتني بفكرتك.","الربيع يذكّرنا أن التغيير يحتاج وقتاً.","لاحظ الألوان حولك وابتسم لها.","ازرع عادة جيدة اليوم."],
    odulodasi:["المكافأة تذكير بالجهد الجميل.","افرح بنجاحك دون أن تنسى التواضع.","كل إنجاز صغير يستحق ملاحظة لطيفة.","شجّع نفسك بكلمة طيبة.","النتيجة الجميلة تبدأ بعادة جيدة."],
    nefes:["تنفس ببطء ليهدأ التفكير.","قف لحظة قبل أن تتكلم عند الغضب.","الراحة ليست كسلاً؛ إنها شحن للطاقة.","سمّ شعورك لتتعامل معه بهدوء.","نفس عميق يساعدك على العودة للتركيز."],
    para:["المشاركة تجعل الفرح أكبر.","استخدم ما لديك بحكمة ولا تبالغ.","العطاء الصغير قد يسعد قلباً كبيراً.","تعلّم الفرق بين الحاجة والرغبة.","الكرم يبدأ بملاحظة من يحتاج المساعدة."],
    arapca:["كل حرف جديد يفتح نافذة معرفة.","استمع للحرف ثم كرره بهدوء.","اللغات تقرّب الناس من بعضهم.","اكتب الحرف ببطء لتتعلمه جيداً.","احترام لغة الآخرين يوسّع عالمك."],
    gizli:["السر الجميل يظهر عندما تلاحظ التفاصيل.","افتح الفضول بسؤال ذكي.","الأشياء الصغيرة قد تخبئ معنى كبيراً.","فكّر بهدوء قبل أن تختار.","الاكتشاف يحتاج عيناً منتبهة."],
    english:["تعلم كلمة إنجليزية جديدة يفتح باب تواصل.","انطق ببطء ولا تخف من التجربة.","استخدم الكلمة في جملة قصيرة.","اللغة تكبر بالتكرار اللطيف.","كل كلمة جديدة تقرّبك من عالم أوسع."],
    deutsch:["تعلم كلمة ألمانية جديدة يقوي التواصل.","كرر الكلمة بهدوء حتى تثبت.","استخدم الكلمة في موقف صغير.","اللغة تحتاج صبراً وابتسامة.","كل جملة قصيرة خطوة للأمام."],
    okyanus:["المحيط يعلّمنا العمق والهدوء.","حافظ على الماء نظيفاً للحياة البحرية.","كل كائن بحري له دور في التوازن.","راقب الأمواج وتعلم الصبر.","لا تترك البلاستيك يصل إلى البحر."],
    atlas:["كل بلد يحمل قصة وثقافة.","احترام الاختلاف يجعل العالم أجمل.","الخريطة تعلّمنا أن العالم واسع ومتنوع.","اسأل عن ثقافة جديدة باحترام.","السفر يبدأ بالفضول والمعرفة."],
